(() => {
const el=id=>document.getElementById(id),meeting=el('meeting'),room=meeting.querySelector('.room'),aside=meeting.querySelector('aside'),caption=room.querySelector('.caption');
const workspace=document.createElement('div');workspace.className='lesson-workspace';room.insertBefore(workspace,el('tiles'));workspace.append(el('screenStage'),el('tiles'),caption);
aside.id='lessonPanel';aside.hidden=true;
const actions=document.createElement('div');actions.className='room-actions';const quick=document.createElement('button');quick.textContent='Ativar tradução';quick.className='primary';quick.id='quickTranslate';quick.onclick=()=>{if(el('prepareTranslate').disabled){phase.textContent='Aguarde a aprovação para ativar tradução.';return}panel(true);el('prepareTranslate').click()};const toggle=document.createElement('button');toggle.id='panelToggle';toggle.textContent='Idiomas e transcrição';toggle.setAttribute('aria-controls','lessonPanel');toggle.setAttribute('aria-expanded','false');actions.append(quick,toggle);room.querySelector('.roomhead').append(actions);
function panel(open){aside.hidden=!open;meeting.classList.toggle('panel-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.classList.toggle('selected',open)}toggle.onclick=()=>panel(aside.hidden);
const close=document.createElement('button');close.className='panel-close';close.textContent='Fechar painel';close.onclick=()=>panel(false);aside.prepend(close);
const invite=room.querySelector('.invite'),details=document.createElement('details');details.className='invite-details';const summary=document.createElement('summary');summary.textContent='Convidar aluno';invite.before(details);details.append(summary,invite);
const head=document.createElement('div');head.className='caption-heading';const identity=document.createElement('div');identity.className='caption-identity';const speaker=document.createElement('strong');speaker.id='captionSpeaker';speaker.textContent='Conversa da aula';const phase=document.createElement('span');phase.id='captionPhase';phase.textContent='Aguardando fala';identity.append(speaker,phase);head.append(identity);
const tools=document.createElement('div');tools.className='caption-tools';
const label=document.createElement('label');label.textContent='Letra';const size=document.createElement('select');size.id='captionSize';size.setAttribute('aria-label','Tamanho da legenda');for(const [value,name]of [[20,'Normal'],[26,'Grande'],[32,'Muito grande']]){const o=document.createElement('option');o.value=value;o.textContent=name;size.append(o)}label.append(size);
const originalLabel=document.createElement('label');originalLabel.className='original-toggle';const originalToggle=document.createElement('input');originalToggle.type='checkbox';originalToggle.id='showOriginal';originalLabel.append(originalToggle,document.createTextNode('Original'));
const expand=document.createElement('button');expand.id='expandCaption';expand.textContent='Expandir';expand.setAttribute('aria-pressed','false');expand.onclick=()=>{const expanded=caption.classList.toggle('caption-expanded');expand.setAttribute('aria-pressed',String(expanded));expand.textContent=expanded?'Recolher':'Expandir'};
const floating=document.createElement('button');floating.id='floatingCaption';floating.textContent='Legenda flutuante';floating.title='Acompanhar a tradução enquanto apresenta em outro programa';
tools.append(label,originalLabel,expand,floating);head.append(tools);caption.prepend(head);const language=caption.querySelector('.eyebrow');language.classList.add('caption-language');
const original=el('original');original.hidden=true;
try{size.value=localStorage.getItem('captionSize')||'26';originalToggle.checked=localStorage.getItem('showOriginal')==='true'}catch{};
function applyPreferences(){caption.style.setProperty('--caption-font',size.value+'px');original.hidden=!originalToggle.checked;try{localStorage.setItem('captionSize',size.value);localStorage.setItem('showOriginal',String(originalToggle.checked))}catch{}updateFloating()}
size.onchange=applyPreferences;originalToggle.onchange=applyPreferences;
let wasSharing=false,pip;
function syncLayout(){const sharing=!el('screenStage').hidden;meeting.classList.toggle('presenting',sharing);if(sharing&&!wasSharing){panel(false);details.open=false}wasSharing=sharing}
new MutationObserver(syncLayout).observe(el('screenStage'),{attributes:true,attributeFilter:['hidden']});syncLayout();
function updateFloating(){if(!pip||pip.closed)return;pip.document.getElementById('floatingSpeaker').textContent=speaker.textContent;pip.document.getElementById('floatingPhase').textContent=phase.textContent;pip.document.getElementById('floatingText').textContent=el('caption').textContent;pip.document.getElementById('floatingText').style.fontSize=size.value+'px';const p=pip.document.getElementById('floatingOriginal');p.hidden=!originalToggle.checked;p.textContent=original.textContent}
floating.onclick=async()=>{if(pip&&!pip.closed){pip.close();return}if(!window.documentPictureInPicture){phase.textContent='Janela flutuante indisponível neste navegador. Use Chrome atualizado.';return}floating.disabled=true;let expired=false,timer;try{const request=documentPictureInPicture.requestWindow({width:560,height:230});request.then(win=>{if(expired)win.close()}).catch(()=>{});pip=await Promise.race([request,new Promise((_,reject)=>{timer=setTimeout(()=>{expired=true;reject(new Error('timeout'))},4500)})]);clearTimeout(timer);const doc=pip.document;doc.title='Aula Global — legenda';doc.body.innerHTML='<style>body{background:#14221b;color:#eef8f2;font:14px system-ui;margin:0;padding:18px}header{display:flex;justify-content:space-between;gap:12px}strong{color:#9fe3c4}span{font-size:11px;color:#aec3b6}p{line-height:1.4;margin:12px 0;overflow-wrap:anywhere}small{color:#adbdB3;line-height:1.5;display:block}</style><header><strong id="floatingSpeaker"></strong><span id="floatingPhase"></span></header><p id="floatingText"></p><small id="floatingOriginal"></small>';floating.textContent='Fechar legenda flutuante';pip.addEventListener('pagehide',()=>{pip=null;floating.textContent='Legenda flutuante'});updateFloating()}catch{phase.textContent='Não foi possível abrir a janela flutuante. Abra a aula diretamente no Chrome.'}finally{clearTimeout(timer);floating.disabled=false}};
new MutationObserver(updateFloating).observe(caption,{childList:true,subtree:true,characterData:true});
window.captionUI={set(name,text,originalText,language,status){speaker.textContent=name;el('caption').textContent=text;original.textContent=originalText;el('captionLanguage').textContent=language;phase.textContent=status;el('caption').title=text;for(const tile of el('tiles').querySelectorAll('.tile'))tile.classList.toggle('last-speaker',tile.dataset.name===name||(tile.id==='selfTile'&&el('selfName').textContent===name));updateFloating()},phase(text){phase.textContent=text;updateFloating()},openPanel:()=>panel(true),closeFloating(){pip?.close()}};
applyPreferences();window.addEventListener('pagehide',()=>pip?.close());
})();

